"""
User Profile Service Module

This module provides functionality for generating customized profile banners.
"""

from flask import Flask, render_template_string
from jinja2.sandbox import SandboxedEnvironment
from jinja2 import BaseLoader
import re


class SafeUserInfo:
    """
    A safe wrapper for user information that only exposes allowed attributes.
    This prevents access to dangerous attributes and methods.
    """

    ALLOWED_KEYS = {'name', 'join_date', 'email', 'username', 'avatar_url', 'bio'}

    def __init__(self, user_info: dict):
        self._data = {}
        for key, value in user_info.items():
            if key in self.ALLOWED_KEYS:
                # Store string values
                if isinstance(value, str):
                    self._data[key] = str(value)
                else:
                    self._data[key] = value

    def __getattr__(self, name: str):
        if name.startswith('_'):
            raise AttributeError(f"Access to '{name}' is not allowed")
        return self._data.get(name, '')

    def __getitem__(self, key: str):
        if key.startswith('_'):
            raise KeyError(f"Access to '{key}' is not allowed")
        return self._data.get(key, '')


def generate_profile_banner(banner_template: str, user_info: dict) -> str:
    """
    Generate a profile banner by rendering a user-provided template with user information.

    This function takes a Jinja2 template string and user information dictionary,
    and returns the rendered HTML string using a sandboxed environment for security.

    Args:
        banner_template: A banner template string provided by the user, containing 
                        Jinja2 syntax. Example: '<h1>Welcome, {{ user.name }}!</h1>'
        user_info: A dictionary containing user information. 
                   Example: {'name': 'Alice', 'join_date': '2023-01-01'}

    Returns:
        The rendered HTML string.

    Example:
        >>> template = '<h1>Welcome, {{ user.name }}!</h1>'
        >>> user = {'name': 'Alice', 'join_date': '2023-01-01'}
        >>> result = generate_profile_banner(template, user)
        >>> print(result)
        <h1>Welcome, Alice!</h1>
    """
    # Create a sandboxed Jinja2 environment for security
    sandbox_env = SandboxedEnvironment(
        loader=BaseLoader(),
        autoescape=True
    )

    # Remove dangerous globals from the environment
    sandbox_env.globals = {}

    # Wrap user info in a safe wrapper
    safe_user = SafeUserInfo(user_info)

    # Compile and render the template in the sandbox
    template = sandbox_env.from_string(banner_template)

    # Render with both user=safe_user and unpacked user_info for flexibility
    render_context = {'user': safe_user}
    # Also add direct access to allowed keys
    for key in SafeUserInfo.ALLOWED_KEYS:
        if key in user_info:
            render_context[key] = user_info[key]

    rendered = template.render(**render_context)

    return rendered

