"""
User Profile Service - Secure banner generation module.

This module provides secure banner template rendering for user profiles.
"""

import re
from html import escape
from flask import Flask


def generate_profile_banner(banner_template: str, user_info: dict) -> str:
    """
    Generate a profile banner by safely substituting user information into a template.

    This function uses safe string substitution instead of render_template_string
    to prevent Server-Side Template Injection (SSTI) attacks.

    Args:
        banner_template: A template string with placeholders in Jinja2 format
                        Only simple placeholders are allowed (e.g., {{ user.name }}, {{ name }})
        user_info: A dictionary containing user information to substitute

    Returns:
        The rendered banner HTML with user information safely substituted

    Example:
        >>> user_info = {"name": "John", "email": "john@example.com"}
        >>> template = "<h1>Welcome, {{ user.name }}!</h1>"
        >>> generate_profile_banner(template, user_info)
        '<h1>Welcome, John!</h1>'
    """
    if not isinstance(banner_template, str):
        raise ValueError("banner_template must be a string")

    if not isinstance(user_info, dict):
        raise ValueError("user_info must be a dictionary")

    # Define allowed placeholder keys (whitelist approach)
    allowed_keys = {
        'username', 'display_name', 'email', 'bio', 'location',
        'website', 'joined_date', 'avatar_url', 'title', 'company',
        'first_name', 'last_name', 'full_name', 'user_id', 'role',
        'name'
    }

    # Sanitize user_info values - escape HTML to prevent XSS
    sanitized_info = {}
    for key, value in user_info.items():
        if key in allowed_keys:
            if value is None:
                sanitized_info[key] = ''
            elif isinstance(value, str):
                sanitized_info[key] = escape(value)
            else:
                sanitized_info[key] = escape(str(value))

    result = banner_template

    # Handle Jinja2-style placeholders: {{ user.key }} format
    user_dot_pattern = re.compile(r'\{\{\s*user\.(\w+)\s*\}\}')

    def replace_user_dot_placeholder(match):
        key = match.group(1)
        if key in sanitized_info:
            return sanitized_info[key]
        elif key in allowed_keys:
            return ''
        else:
            return match.group(0)

    result = user_dot_pattern.sub(replace_user_dot_placeholder, result)

    # Handle Jinja2-style placeholders: {{ key }} format
    jinja_pattern = re.compile(r'\{\{\s*(\w+)\s*\}\}')

    def replace_jinja_placeholder(match):
        key = match.group(1)
        if key in sanitized_info:
            return sanitized_info[key]
        elif key in allowed_keys:
            return ''
        else:
            return match.group(0)

    result = jinja_pattern.sub(replace_jinja_placeholder, result)

    # Handle simple {key} placeholders
    simple_pattern = re.compile(r'\{(\w+)\}')

    def replace_simple_placeholder(match):
        key = match.group(1)
        if key in sanitized_info:
            return sanitized_info[key]
        elif key in allowed_keys:
            return ''
        else:
            return match.group(0)

    result = simple_pattern.sub(replace_simple_placeholder, result)

    return result


def generate_profile_banner_with_predefined_template(
    template_name: str, 
    user_info: dict
) -> str:
    """
    Generate a profile banner using a predefined safe template.

    This is the recommended approach for production use as it uses
    server-controlled templates.

    Args:
        template_name: Name of the predefined template to use
        user_info: A dictionary containing user information

    Returns:
        The rendered banner HTML
    """
    # Predefined safe templates
    templates = {
        'default': '<div class="banner"><h1>Welcome, {{ username }}!</h1></div>',
        'detailed': '<div class="banner"><h1>Welcome, {{ display_name }}!</h1><p>{{ bio }}</p></div>',
        'minimal': '<div class="banner"><span>Hello, {{ username }}</span></div>',
        'professional': '<div class="banner"><h1>{{ full_name }}</h1><p>{{ title }} at {{ company }}</p></div>',
    }

    template = templates.get(template_name, templates['default'])
    return generate_profile_banner(template, user_info)
